 static int kcm_write_msgs(struct kcm_sock *kcm)
 {
 	unsigned int total_sent = 0;
 	struct sock *sk = &kcm->sk;
 	struct kcm_psock *psock;
 	struct sk_buff *head;
 	int ret = 0;

 	kcm->tx_wait_more = false;
 	psock = kcm->tx_psock;
 	if (unlikely(psock && psock->tx_stopped)) {
 		/* A reserved psock was aborted asynchronously. Unreserve
 		 * it and we'll retry the message.
 		 */
 		unreserve_psock(kcm);
 		kcm_report_tx_retry(kcm);
 		if (skb_queue_empty(&sk->sk_write_queue))
 			return 0;

 		kcm_tx_msg(skb_peek(&sk->sk_write_queue))->started_tx = false;
 	}

 retry:
 	while ((head = skb_peek(&sk->sk_write_queue))) {
 		struct msghdr msg = {
 			.msg_flags = MSG_DONTWAIT | MSG_SPLICE_PAGES,
 		};
 		struct kcm_tx_msg *txm = kcm_tx_msg(head);
 		struct sk_buff *skb;
 		unsigned int msize;
 		int i;

 		if (!txm->started_tx) {
 			psock = reserve_psock(kcm);
 			if (!psock)
 				goto out;
 			skb = head;
 			txm->frag_offset = 0;
 			txm->sent = 0;
 			txm->started_tx = true;
 		} else {
 			if (WARN_ON(!psock)) {
 				ret = -EINVAL;
 				goto out;
 			}
 			skb = txm->frag_skb;
 		}

-		if (WARN_ON(!skb_shinfo(skb)->nr_frags) ||
+		if (WARN_ON_ONCE(!skb_shinfo(skb)->nr_frags) ||
 		    WARN_ON_ONCE(!skb_frag_page(&skb_shinfo(skb)->frags[0]))) {
 			ret = -EINVAL;
 			goto out;
 		}

 		msize = 0;
 		for (i = 0; i < skb_shinfo(skb)->nr_frags; i++)
 			msize += skb_frag_size(&skb_shinfo(skb)->frags[i]);

 		iov_iter_bvec(&msg.msg_iter, ITER_SOURCE,
 			      (const struct bio_vec *)skb_shinfo(skb)->frags,
 			      skb_shinfo(skb)->nr_frags, msize);
 		iov_iter_advance(&msg.msg_iter, txm->frag_offset);

 		do {
 			ret = sock_sendmsg(psock->sk->sk_socket, &msg);
 			if (ret <= 0) {
 				if (ret == -EAGAIN) {
 					/* Save state to try again when there's
 					 * write space on the socket
 					 */
 					txm->frag_skb = skb;
 					ret = 0;
 					goto out;
 				}

 				/* Hard failure in sending message, abort this
 				 * psock since it has lost framing
 				 * synchronization and retry sending the
 				 * message from the beginning.
 				 */
 				kcm_abort_tx_psock(psock, ret ? -ret : EPIPE,
 						   true);
 				unreserve_psock(kcm);
 				psock = NULL;

 				txm->started_tx = false;
 				kcm_report_tx_retry(kcm);
 				ret = 0;
 				goto retry;
 			}

 			txm->sent += ret;
 			txm->frag_offset += ret;
 			KCM_STATS_ADD(psock->stats.tx_bytes, ret);
 		} while (msg.msg_iter.count > 0);

 		if (skb == head) {
 			if (skb_has_frag_list(skb)) {
 				txm->frag_skb = skb_shinfo(skb)->frag_list;
 				txm->frag_offset = 0;
 				continue;
 			}
 		} else if (skb->next) {
 			txm->frag_skb = skb->next;
 			txm->frag_offset = 0;
 			continue;
 		}

 		/* Successfully sent the whole packet, account for it. */
 		sk->sk_wmem_queued -= txm->sent;
 		total_sent += txm->sent;
 		skb_dequeue(&sk->sk_write_queue);
 		kfree_skb(head);
 		KCM_STATS_INCR(psock->stats.tx_msgs);
 	}
 out:
 	if (!head) {
 		/* Done with all queued messages. */
 		WARN_ON(!skb_queue_empty(&sk->sk_write_queue));
 		if (psock)
 			unreserve_psock(kcm);
 	}

 	/* Check if write space is available */
 	sk->sk_write_space(sk);

 	return total_sent ? : ret;
 }


 static int kcm_sendmsg(struct socket *sock, struct msghdr *msg, size_t len)
 {
 	struct sock *sk = sock->sk;
 	struct kcm_sock *kcm = kcm_sk(sk);
-	struct sk_buff *skb = NULL, *head = NULL;
+	struct sk_buff *skb = NULL, *head = NULL, *frag_prev = NULL;
 	size_t copy, copied = 0;
 	long timeo = sock_sndtimeo(sk, msg->msg_flags & MSG_DONTWAIT);
 	int eor = (sock->type == SOCK_DGRAM) ?
 		  !(msg->msg_flags & MSG_MORE) : !!(msg->msg_flags & MSG_EOR);
 	int err = -EPIPE;

 	mutex_lock(&kcm->tx_mutex);
 	lock_sock(sk);

 	/* Per tcp_sendmsg this should be in poll */
 	sk_clear_bit(SOCKWQ_ASYNC_NOSPACE, sk);

 	if (sk->sk_err)
 		goto out_error;

 	if (kcm->seq_skb) {
 		/* Previously opened message */
 		head = kcm->seq_skb;
 		skb = kcm_tx_msg(head)->last_skb;
 		goto start;
 	}

 	/* Call the sk_stream functions to manage the sndbuf mem. */
 	if (!sk_stream_memory_free(sk)) {
 		kcm_push(kcm);
 		set_bit(SOCK_NOSPACE, &sk->sk_socket->flags);
 		err = sk_stream_wait_memory(sk, &timeo);
 		if (err)
 			goto out_error;
 	}

 	if (msg_data_left(msg)) {
 		/* New message, alloc head skb */
 		head = alloc_skb(0, sk->sk_allocation);
 		while (!head) {
 			kcm_push(kcm);
 			err = sk_stream_wait_memory(sk, &timeo);
 			if (err)
 				goto out_error;

 			head = alloc_skb(0, sk->sk_allocation);
 		}

 		skb = head;

 		/* Set ip_summed to CHECKSUM_UNNECESSARY to avoid calling
 		 * csum_and_copy_from_iter from skb_do_copy_data_nocache.
 		 */
 		skb->ip_summed = CHECKSUM_UNNECESSARY;
 	}

 start:
 	while (msg_data_left(msg)) {
 		bool merge = true;
 		int i = skb_shinfo(skb)->nr_frags;
 		struct page_frag *pfrag = sk_page_frag(sk);

 		if (!sk_page_frag_refill(sk, pfrag))
 			goto wait_for_memory;

 		if (!skb_can_coalesce(skb, i, pfrag->page,
 				      pfrag->offset)) {
 			if (i == MAX_SKB_FRAGS) {
 				struct sk_buff *tskb;

 				tskb = alloc_skb(0, sk->sk_allocation);
 				if (!tskb)
 					goto wait_for_memory;

 				if (head == skb)
 					skb_shinfo(head)->frag_list = tskb;
 				else
 					skb->next = tskb;

+				frag_prev = skb;
 				skb = tskb;
 				skb->ip_summed = CHECKSUM_UNNECESSARY;
 				continue;
 			}
 			merge = false;
 		}

 		if (msg->msg_flags & MSG_SPLICE_PAGES) {
 			copy = msg_data_left(msg);
 			if (!sk_wmem_schedule(sk, copy))
 				goto wait_for_memory;

 			err = skb_splice_from_iter(skb, &msg->msg_iter, copy);
 			if (err < 0) {
 				if (err == -EMSGSIZE)
 					goto wait_for_memory;
 				goto out_error;
 			}

 			copy = err;
 			skb_shinfo(skb)->flags |= SKBFL_SHARED_FRAG;
 			sk_wmem_queued_add(sk, copy);
 			sk_mem_charge(sk, copy);

 			if (head != skb)
 				head->truesize += copy;
 		} else {
 			copy = min_t(int, msg_data_left(msg),
 				     pfrag->size - pfrag->offset);
 			if (!sk_wmem_schedule(sk, copy))
 				goto wait_for_memory;

 			err = skb_copy_to_page_nocache(sk, &msg->msg_iter, skb,
 						       pfrag->page,
 						       pfrag->offset,
 						       copy);
 			if (err)
 				goto out_error;

 			/* Update the skb. */
 			if (merge) {
 				skb_frag_size_add(
 					&skb_shinfo(skb)->frags[i - 1], copy);
 			} else {
 				skb_fill_page_desc(skb, i, pfrag->page,
 						   pfrag->offset, copy);
 				get_page(pfrag->page);
 			}

 			pfrag->offset += copy;
 		}

 		copied += copy;
 		if (head != skb) {
 			head->len += copy;
 			head->data_len += copy;
 		}

 		continue;

 wait_for_memory:
 		kcm_push(kcm);
 		err = sk_stream_wait_memory(sk, &timeo);
 		if (err)
 			goto out_error;
 	}

